<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Walking Alpaca</title>
<style>
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }
  html, body {
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    background: #1d1826;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  canvas {
    display: block;
    width: 100vw;
    height: 100vh;
  }
</style>
</head>
<body>
<canvas id="scene"></canvas>
<script>
(() => {
  const canvas = document.getElementById('scene');
  const ctx = canvas.getContext('2d');

  // Virtual coordinate space anchored to 1280x720
  const VW = 1280;
  const VH = 720;
  let dpr = 1;

  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, 2.5);
    canvas.width = Math.round(window.innerWidth * dpr);
    canvas.height = Math.round(window.innerHeight * dpr);
  }
  window.addEventListener('resize', resize);
  resize();

  // Deterministic PRNG for procedural scenery elements
  function mulberry32(a) {
    return function() {
      let t = a += 0x6D2B79F5;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  const rand = mulberry32(4219);

  // Gait & physics constants (mathematically locked so hooves never slip)
  const CYCLE_DURATION = 1.38;     // seconds per full 4-beat gait cycle
  const STANCE_RATIO = 0.58;       // fraction of cycle each foot is on the ground
  const STRIDE_LENGTH = 114;       // pixels covered during stance
  const GROUND_SPEED = STRIDE_LENGTH / (STANCE_RATIO * CYCLE_DURATION); // exact ground velocity
  const GROUND_Y = 588;

  // Pre-generate clouds
  const clouds = Array.from({ length: 7 }, (_, i) => ({
    x: i * 240 + rand() * 120,
    y: 75 + rand() * 150,
    scale: 0.65 + rand() * 0.65,
    speed: 8 + rand() * 7,
    puffs: Array.from({ length: 5 }, (__, j) => ({
      ox: (j - 2) * 34 + (rand() - 0.5) * 14,
      oy: Math.abs(j - 2) * 7 + (rand() - 0.5) * 8,
      r: 26 + (2 - Math.abs(j - 2)) * 12 + rand() * 8
    }))
  }));

  // Pre-generate floating golden sun motes
  const motes = Array.from({ length: 28 }, () => ({
    x: rand() * VW,
    y: 80 + rand() * 440,
    r: 1.2 + rand() * 2.2,
    speedX: 10 + rand() * 18,
    phase: rand() * Math.PI * 2,
    alpha: 0.2 + rand() * 0.45
  }));

  // Pre-generate meadow tufts & Andean wildflowers (scrolling loop width = 1600)
  const LOOP_W = 1600;
  const meadowItems = Array.from({ length: 46 }, () => {
    const type = rand() < 0.35 ? 'flower' : (rand() < 0.5 ? 'ichu' : 'shrub');
    const flowerColors = ['#e86f88', '#f4b942', '#9b7ede', '#ff8c61'];
    return {
      x: rand() * LOOP_W,
      yOffset: (rand() - 0.5) * 26,
      scale: 0.7 + rand() * 0.55,
      type,
      color: flowerColors[Math.floor(rand() * flowerColors.length)],
      seed: rand() * Math.PI * 2
    };
  }).sort((a, b) => a.yOffset - b.yOffset);

  // Pre-generate trail pebbles & texture marks
  const pebbles = Array.from({ length: 55 }, () => ({
    x: rand() * LOOP_W,
    y: GROUND_Y - 12 + rand() * 68,
    rx: 3 + rand() * 7,
    ry: 1.6 + rand() * 3,
    shade: rand() < 0.5 ? '#c69c78' : '#dfba98',
    rot: (rand() - 0.5) * 0.5
  }));

  // Foreground grass silhouettes
  const fgBlades = Array.from({ length: 18 }, () => ({
    x: rand() * LOOP_W,
    h: 42 + rand() * 48,
    lean: (rand() - 0.5) * 22,
    phase: rand() * Math.PI * 2
  }));

  // Dynamic footstep dust particles
  const dustParticles = [];
  const legOrder = [
    { id: 'BL', phaseOffset: 0.00, isFront: false, isNear: false },
    { id: 'FL', phaseOffset: 0.25, isFront: true,  isNear: false },
    { id: 'BR', phaseOffset: 0.50, isFront: false, isNear: true  },
    { id: 'FR', phaseOffset: 0.75, isFront: true,  isNear: true  }
  ];
  const prevInStance = { BL: true, FL: true, BR: true, FR: true };

  function spawnDust(x, y, isNear) {
    const count = isNear ? 5 : 3;
    for (let i = 0; i < count; i++) {
      dustParticles.push({
        x: x + (Math.random() - 0.5) * 10,
        y: y - 2 + (Math.random() - 0.5) * 4,
        vx: -GROUND_SPEED * (0.55 + Math.random() * 0.35) - Math.random() * 18,
        vy: -12 - Math.random() * 22,
        r: (isNear ? 4.5 : 3.2) + Math.random() * 4,
        life: 0,
        maxLife: 0.45 + Math.random() * 0.3,
        alpha: isNear ? 0.38 : 0.22
      });
    }
  }

  // 2-Bone Inverse Kinematics solver
  function solveIK(hx, hy, fx, fy, L1, L2, bendDir) {
    let dx = fx - hx;
    let dy = fy - hy;
    let d = Math.hypot(dx, dy);
    const minD = Math.abs(L1 - L2) + 0.5;
    const maxD = (L1 + L2) * 0.998;
    if (d < minD) d = minD;
    if (d > maxD) {
      dx = (dx / d) * maxD;
      dy = (dy / d) * maxD;
      d = maxD;
    }
    const a = (L1 * L1 - L2 * L2 + d * d) / (2 * d);
    const h = Math.sqrt(Math.max(0, L1 * L1 - a * a));
    const ux = dx / d;
    const uy = dy / d;
    const mx = hx + a * ux;
    const my = hy + a * uy;
    // Perpendicular (-uy, ux) points Left (-X) when dy > 0
    const px = -uy * bendDir;
    const py = ux * bendDir;
    return {
      kx: mx + h * px,
      ky: my + h * py,
      fx: hx + dx,
      fy: hy + dy
    };
  }

  // Compute foot target & toe angle for a given phase [0..1)
  function getFootTarget(originX, groundY, phase, liftHeight) {
    const p = ((phase % 1) + 1) % 1;
    let x, y, footAngle, inStance;

    if (p < STANCE_RATIO) {
      // Stance phase: linear backward motion locked to ground scroll speed
      const u = p / STANCE_RATIO;
      x = originX + STRIDE_LENGTH * (0.5 - u);
      y = groundY;
      footAngle = 0;
      inStance = true;
    } else {
      // Swing phase: smooth forward arc with gentle heel peel and soft landing
      const u = (p - STANCE_RATIO) / (1 - STANCE_RATIO);
      const easeX = 0.5 - 0.5 * Math.cos(Math.PI * u);
      x = originX - STRIDE_LENGTH * 0.5 + STRIDE_LENGTH * easeX;

      // Skewed sine lift so foot clears ground briskly and descends smoothly
      const liftProfile = Math.sin(Math.PI * Math.pow(u, 0.82));
      y = groundY - liftHeight * liftProfile;

      // Camelid foot pad tilts down/back slightly on lift, levels out before touch-down
      footAngle = Math.sin(Math.PI * u) * 0.48 * (1 - u * 0.35);
      inStance = false;
    }
    return { x, y, footAngle, inStance };
  }

  // Helper: Draw a fluffy cloud-scalloped closed shape from circle puffs
  function fillPuffCluster(puffs, fillStyle) {
    ctx.fillStyle = fillStyle;
    ctx.beginPath();
    for (let i = 0; i < puffs.length; i++) {
      const p = puffs[i];
      ctx.moveTo(p.x + p.r, p.y);
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    }
    ctx.fill();
  }

  // Draw Sky, Sun & Atmospheric Glow
  function drawSky(t) {
    const skyGrad = ctx.createLinearGradient(0, 0, 0, GROUND_Y);
    skyGrad.addColorStop(0.00, '#3e497a');
    skyGrad.addColorStop(0.28, '#7b6d9d');
    skyGrad.addColorStop(0.58, '#d98c8c');
    skyGrad.addColorStop(0.84, '#f7be8f');
    skyGrad.addColorStop(1.00, '#fce0b6');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, VW, VH);

    // Warm golden-hour sun on upper right-left horizon
    const sunX = 960;
    const sunY = 215;
    const pulse = 1 + Math.sin(t * 0.9) * 0.025;

    const halo = ctx.createRadialGradient(sunX, sunY, 15, sunX, sunY, 340 * pulse);
    halo.addColorStop(0.0, 'rgba(255, 248, 220, 0.85)');
    halo.addColorStop(0.18, 'rgba(255, 224, 168, 0.45)');
    halo.addColorStop(0.5, 'rgba(249, 178, 130, 0.14)');
    halo.addColorStop(1.0, 'rgba(249, 178, 130, 0)');
    ctx.fillStyle = halo;
    ctx.fillRect(0, 0, VW, GROUND_Y);

    ctx.fillStyle = '#fff9e6';
    ctx.beginPath();
    ctx.arc(sunX, sunY, 44, 0, Math.PI * 2);
    ctx.fill();

    // Soft clouds
    for (const c of clouds) {
      const cx = ((c.x - t * c.speed) % (VW + 360) + (VW + 360)) % (VW + 360) - 180;
      ctx.save();
      ctx.translate(cx, c.y);
      ctx.scale(c.scale, c.scale);

      // Cloud shadow base
      ctx.fillStyle = 'rgba(219, 152, 158, 0.45)';
      ctx.beginPath();
      for (const p of c.puffs) {
        ctx.moveTo(p.ox + p.r, p.oy + 5);
        ctx.arc(p.ox, p.oy + 5, p.r, 0, Math.PI * 2);
      }
      ctx.fill();

      // Cloud warm lit body
      const cg = ctx.createLinearGradient(0, -35, 0, 28);
      cg.addColorStop(0, '#fff7eb');
      cg.addColorStop(1, '#f7d5c6');
      ctx.fillStyle = cg;
      ctx.beginPath();
      for (const p of c.puffs) {
        ctx.moveTo(p.ox + p.r, p.oy);
        ctx.arc(p.ox, p.oy, p.r, 0, Math.PI * 2);
      }
      ctx.fill();
      ctx.restore();
    }
  }

  // Draw Layered Andean Mountains & Hills
  function drawMountains(scrollDist) {
    // Layer 1: Distant snow-capped Cordillera peaks
    const p1 = (scrollDist * 0.035) % 1280;
    for (let rep = -1; rep <= 1; rep++) {
      const ox = rep * 1280 - p1;
      ctx.save();
      ctx.translate(ox, 0);

      const mGrad = ctx.createLinearGradient(0, 170, 0, 470);
      mGrad.addColorStop(0, '#8d789f');
      mGrad.addColorStop(0.55, '#b68fa6');
      mGrad.addColorStop(1, '#e4b4a6');
      ctx.fillStyle = mGrad;

      ctx.beginPath();
      ctx.moveTo(0, 460);
      ctx.lineTo(140, 285);
      ctx.lineTo(255, 345);
      ctx.lineTo(430, 185);
      ctx.lineTo(590, 325);
      ctx.lineTo(745, 225);
      ctx.lineTo(910, 340);
      ctx.lineTo(1090, 205);
      ctx.lineTo(1280, 460);
      ctx.closePath();
      ctx.fill();

      // sunlit snow caps on right-facing slopes
      ctx.fillStyle = 'rgba(255, 246, 236, 0.72)';
      const peaks = [
        [430, 185, 376, 235, 488, 242],
        [745, 225, 700, 266, 795, 272],
        [1090, 205, 1040, 250, 1142, 262],
        [140, 285, 106, 318, 178, 322]
      ];
      for (const pk of peaks) {
        ctx.beginPath();
        ctx.moveTo(pk[0], pk[1]);
        ctx.lineTo(pk[2], pk[3]);
        ctx.lineTo(pk[0] - 8, pk[3] + 10);
        ctx.lineTo(pk[0] + 12, pk[3] - 2);
        ctx.lineTo(pk[4], pk[5]);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }

    // Soft valley mist band
    const mist = ctx.createLinearGradient(0, 340, 0, 470);
    mist.addColorStop(0, 'rgba(252, 219, 194, 0)');
    mist.addColorStop(0.6, 'rgba(252, 219, 194, 0.45)');
    mist.addColorStop(1, 'rgba(252, 219, 194, 0.7)');
    ctx.fillStyle = mist;
    ctx.fillRect(0, 340, VW, 130);

    // Layer 2: Midground warm terracotta / Rainbow-mountain-inspired ridges
    const p2 = (scrollDist * 0.11) % 1280;
    for (let rep = -1; rep <= 1; rep++) {
      const ox = rep * 1280 - p2;
      ctx.save();
      ctx.translate(ox, 0);

      const rGrad = ctx.createLinearGradient(0, 320, 0, 510);
      rGrad.addColorStop(0, '#9e6f7d');
      rGrad.addColorStop(0.45, '#b87f7c');
      rGrad.addColorStop(1, '#d39e85');
      ctx.fillStyle = rGrad;

      ctx.beginPath();
      ctx.moveTo(0, 500);
      ctx.bezierCurveTo(180, 360, 310, 355, 490, 425);
      ctx.bezierCurveTo(660, 485, 790, 330, 980, 365);
      ctx.bezierCurveTo(1110, 390, 1190, 445, 1280, 500);
      ctx.closePath();
      ctx.fill();

      // Subtle mineral strata ribbons
      ctx.strokeStyle = 'rgba(238, 189, 152, 0.28)';
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.moveTo(40, 465);
      ctx.bezierCurveTo(200, 385, 310, 382, 470, 438);
      ctx.moveTo(690, 452);
      ctx.bezierCurveTo(810, 368, 930, 365, 1120, 428);
      ctx.stroke();

      ctx.restore();
    }

    // Layer 3: Rolling altiplano golden-olive hills
    const p3 = (scrollDist * 0.28) % 1280;
    for (let rep = -1; rep <= 1; rep++) {
      const ox = rep * 1280 - p3;
      ctx.save();
      ctx.translate(ox, 0);

      const hGrad = ctx.createLinearGradient(0, 425, 0, 555);
      hGrad.addColorStop(0, '#8ca06c');
      hGrad.addColorStop(0.6, '#768c5d');
      hGrad.addColorStop(1, '#61774e');
      ctx.fillStyle = hGrad;

      ctx.beginPath();
      ctx.moveTo(0, 555);
      ctx.bezierCurveTo(220, 430, 430, 455, 650, 490);
      ctx.bezierCurveTo(860, 522, 1040, 425, 1280, 485);
      ctx.lineTo(1280, 555);
      ctx.closePath();
      ctx.fill();

      // Distant Andean terraces & tiny bushes
      ctx.strokeStyle = 'rgba(218, 212, 148, 0.22)';
      ctx.lineWidth = 2.5;
      for (let k = 0; k < 3; k++) {
        ctx.beginPath();
        ctx.moveTo(140 + k * 25, 478 + k * 14);
        ctx.quadraticCurveTo(280, 458 + k * 14, 410 - k * 20, 482 + k * 14);
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  // Draw Near Meadow, Ichu Grass, Wildflowers & Sandy Trail
  function drawGroundAndMeadow(scrollDist, t) {
    // Meadow bank behind path
    const mGrad = ctx.createLinearGradient(0, 505, 0, 580);
    mGrad.addColorStop(0, '#9ab065');
    mGrad.addColorStop(1, '#6f874b');
    ctx.fillStyle = mGrad;

    const pm = (scrollDist * 0.65) % 1280;
    ctx.beginPath();
    ctx.moveTo(0, 590);
    for (let x = 0; x <= VW + 80; x += 80) {
      const wx = x + pm;
      const y = 524 + Math.sin(wx * 0.006) * 12 + Math.cos(wx * 0.013) * 6;
      ctx.lineTo(x, y);
    }
    ctx.lineTo(VW, 590);
    ctx.closePath();
    ctx.fill();

    // Meadow flora (scrolling at 0.78x)
    const pf = (scrollDist * 0.78) % LOOP_W;
    for (const item of meadowItems) {
      let ix = ((item.x - pf) % LOOP_W + LOOP_W) % LOOP_W - 160;
      if (ix < -80 || ix > VW + 80) continue;
      const iy = 546 + item.yOffset;
      const sway = Math.sin(t * 2.2 + item.seed) * 4 * item.scale;

      ctx.save();
      ctx.translate(ix, iy);
      ctx.scale(item.scale, item.scale);

      if (item.type === 'ichu') {
        // Golden Andean feather grass
        for (let b = -3; b <= 3; b++) {
          ctx.strokeStyle = b % 2 === 0 ? '#dfc77a' : '#b7a960';
          ctx.lineWidth = 2;
          ctx.lineCap = 'round';
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(b * 4 + sway * 0.5, -18, b * 9 + sway, -30 + Math.abs(b) * 3);
          ctx.stroke();
        }
      } else if (item.type === 'shrub') {
        ctx.fillStyle = '#5c7542';
        ctx.beginPath();
        ctx.arc(-8, -5, 9, 0, Math.PI * 2);
        ctx.arc(7, -4, 8, 0, Math.PI * 2);
        ctx.arc(0, -10, 10, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#7e9956';
        ctx.beginPath();
        ctx.arc(1, -12, 8, 0, Math.PI * 2);
        ctx.arc(8, -6, 6, 0, Math.PI * 2);
        ctx.fill();
      } else {
        // Lupine / Andean wildflower stalk
        ctx.strokeStyle = '#57733e';
        ctx.lineWidth = 2.2;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(sway * 0.5, -14, sway, -26);
        ctx.stroke();

        ctx.fillStyle = item.color;
        for (let f = 0; f < 4; f++) {
          const fy = -14 - f * 4.5;
          const fx = sway * ( -fy / 26 );
          ctx.beginPath();
          ctx.arc(fx, fy, 3.6 - f * 0.4, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.restore();
    }

    // Warm sunlit trail (1.0x ground speed)
    const pathGrad = ctx.createLinearGradient(0, 558, 0, VH);
    pathGrad.addColorStop(0.00, '#e8c79e');
    pathGrad.addColorStop(0.16, '#dfb78c');
    pathGrad.addColorStop(0.68, '#c89b72');
    pathGrad.addColorStop(1.00, '#9f7553');
    ctx.fillStyle = pathGrad;

    const pt = scrollDist % 1280;
    ctx.beginPath();
    ctx.moveTo(0, VH);
    for (let x = 0; x <= VW + 80; x += 80) {
      const wx = x + pt;
      const y = 558 + Math.sin(wx * 0.008) * 3.5;
      ctx.lineTo(x, y);
    }
    ctx.lineTo(VW, VH);
    ctx.closePath();
    ctx.fill();

    // Grassy verge border along trail edge
    ctx.strokeStyle = '#859d55';
    ctx.lineWidth = 5;
    ctx.beginPath();
    for (let x = 0; x <= VW + 80; x += 80) {
      const wx = x + pt;
      const y = 558 + Math.sin(wx * 0.008) * 3.5;
      if (x === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Scrolling trail pebbles (exact 1.0x ground lock!)
    const pp = scrollDist % LOOP_W;
    for (const peb of pebbles) {
      const px = ((peb.x - pp) % LOOP_W + LOOP_W) % LOOP_W - 160;
      if (px < -20 || px > VW + 20) continue;
      ctx.save();
      ctx.translate(px, peb.y);
      ctx.rotate(peb.rot);
      ctx.fillStyle = 'rgba(130, 88, 56, 0.28)';
      ctx.beginPath();
      ctx.ellipse(1, 1.8, peb.rx, peb.ry, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = peb.shade;
      ctx.beginPath();
      ctx.ellipse(0, 0, peb.rx, peb.ry, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }

  // Draw a single articulated alpaca leg
  function drawAlpacaLeg(hx, hy, ik, footAngle, isNear, isFront) {
    const fleeceMain  = isNear ? '#f6ecdd' : '#dfd1be';
    const fleeceShade = isNear ? '#eadbc6' : '#cfc0ab';
    const lowerCoat   = isNear ? '#efe2cf' : '#d5c5b0';
    const hoofColor   = isNear ? '#4a3d38' : '#3a2f2b';
    const hoofHi      = isNear ? '#6c5a53' : '#50423d';

    const { kx, ky, fx, fy } = ik;

    // Fluffy upper thigh / forearm cuff
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.strokeStyle = fleeceShade;
    ctx.lineWidth = isFront ? 28 : 32;
    ctx.beginPath();
    ctx.moveTo(hx, hy);
    ctx.lineTo(kx, ky);
    ctx.stroke();

    ctx.strokeStyle = fleeceMain;
    ctx.lineWidth = isFront ? 24 : 28;
    ctx.beginPath();
    ctx.moveTo(hx + 2, hy - 2);
    ctx.lineTo(kx + 1.5, ky - 1);
    ctx.stroke();

    // Fluffy puffs along upper leg
    const midX = (hx + kx) * 0.5;
    const midY = (hy + ky) * 0.5;
    ctx.fillStyle = fleeceMain;
    ctx.beginPath();
    ctx.arc(hx - 4, hy + 10, isFront ? 15 : 18, 0, Math.PI * 2);
    ctx.arc(midX + (isFront ? 5 : -6), midY, isFront ? 13 : 15, 0, Math.PI * 2);
    ctx.arc(kx, ky - 2, 12.5, 0, Math.PI * 2);
    ctx.fill();

    // Slender lower cannon bone (tapered wooly stocking)
    const ankleX = fx - Math.cos(footAngle) * 4;
    const ankleY = fy - 8;

    ctx.strokeStyle = lowerCoat;
    ctx.lineWidth = 15.5;
    ctx.beginPath();
    ctx.moveTo(kx, ky);
    ctx.lineTo(ankleX, ankleY);
    ctx.stroke();

    // Subtle warm sunlit front edge on near legs
    if (isNear) {
      ctx.strokeStyle = '#fbf4e9';
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(kx + 4, ky + 2);
      ctx.lineTo(ankleX + 4, ankleY - 2);
      ctx.stroke();
    }

    // Fetlock fluff & Camelid two-toed soft padded foot
    ctx.save();
    ctx.translate(fx, fy);
    ctx.rotate(footAngle);

    // Padded camelid toes
    ctx.fillStyle = hoofColor;
    ctx.beginPath();
    ctx.moveTo(-10, 0);
    ctx.lineTo(14, 0);
    ctx.quadraticCurveTo(17, -6, 9, -9);
    ctx.lineTo(-7, -9);
    ctx.quadraticCurveTo(-11, -5, -10, 0);
    ctx.closePath();
    ctx.fill();

    // Front toe highlight / split camelid toe hint
    ctx.fillStyle = hoofHi;
    ctx.beginPath();
    ctx.ellipse(9, -3.8, 5, 3.2, -0.2, 0, Math.PI * 2);
    ctx.fill();

    // Soft wool cuff overlapping top of foot
    ctx.fillStyle = lowerCoat;
    ctx.beginPath();
    ctx.ellipse(0, -9, 9.5, 5.5, -0.08, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  // Draw the Hero Alpaca!
  function drawAlpaca(t, dt) {
    const cyclePhase = (t / CYCLE_DURATION) % 1;
    const twoBeat = cyclePhase * Math.PI * 4; // 2 oscillations per full 4-beat cycle

    // Subtle organic body motion: vertical bob + gentle pitch + slight surge
    const bodyBob = Math.sin(twoBeat - 0.5) * 4.6;
    const bodyPitch = Math.sin(twoBeat + 0.4) * 0.018;
    const bodyX = 608 + Math.cos(twoBeat) * 1.8;
    const bodyY = 408 + bodyBob;

    // Hip/shoulder world anchor projections & IK calculation
