  // Update & Draw Footstep Dust Puffs, Sun Motes & Foreground Grass
  function drawParticlesAndForeground(scrollDist, t, dt) {
    // Footstep dust puffs
    for (let i = dustParticles.length - 1; i >= 0; i--) {
      const p = dustParticles[i];
      p.life += dt;
      if (p.life >= p.maxLife) {
        dustParticles.splice(i, 1);
        continue;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 28 * dt;
      const u = p.life / p.maxLife;
      const alpha = p.alpha * (1 - u);
      const radius = p.r * (0.7 + u * 1.1);

      ctx.fillStyle = `rgba(246, 224, 196, ${alpha})`;
      ctx.beginPath();
      ctx.arc(p.x, p.y, radius, 0, Math.PI * 2);
      ctx.fill();
    }

    // Drifting golden atmospheric motes
    for (const m of motes) {
      const mx = ((m.x - t * m.speedX) % VW + VW) % VW;
      const my = m.y + Math.sin(t * 1.4 + m.phase) * 14;
      const twinkle = m.alpha * (0.65 + 0.35 * Math.sin(t * 2.5 + m.phase));
      ctx.fillStyle = `rgba(255, 248, 218, ${twinkle})`;
      ctx.beginPath();
      ctx.arc(mx, my, m.r, 0, Math.PI * 2);
      ctx.fill();
    }

    // Subtle foreground grass blades passing near bottom edge (1.32x parallax)
    const pfg = (scrollDist * 1.32) % LOOP_W;
    ctx.lineCap = 'round';
    for (const b of fgBlades) {
      const bx = ((b.x - pfg) % LOOP_W + LOOP_W) % LOOP_W - 160;
      if (bx < -40 || bx > VW + 40) continue;
      const sway = Math.sin(t * 2.6 + b.phase) * 7;
      ctx.strokeStyle = 'rgba(72, 86, 46, 0.55)';
      ctx.lineWidth = 4.5;
      ctx.beginPath();
      ctx.moveTo(bx, VH + 6);
      ctx.quadraticCurveTo(bx + b.lean * 0.4 + sway * 0.4, VH - b.h * 0.5, bx + b.lean + sway, VH - b.h);
      ctx.stroke();
    }

    // Delicate warm cinematic vignette
    const vig = ctx.createRadialGradient(VW * 0.5, VH * 0.48, VW * 0.36, VW * 0.5, VH * 0.5, VW * 0.66);
    vig.addColorStop(0, 'rgba(42, 24, 34, 0)');
    vig.addColorStop(1, 'rgba(42, 24, 34, 0.24)');
    ctx.fillStyle = vig;
    ctx.fillRect(0, 0, VW, VH);
  }

  // Main Animation Loop
  let lastTime = null;
  let elapsed = 0;

  function frame(now) {
    if (lastTime === null) lastTime = now;
    const dt = Math.min((now - lastTime) / 1000, 0.05);
    lastTime = now;
    elapsed += dt;

    const w = canvas.width;
    const h = canvas.height;

    // Cover viewport seamlessly while preserving 1280x720 composition
    const scale = Math.max(w / VW, h / VH);
    const offsetX = (w - VW * scale) * 0.5;
    const offsetY = (h - VH * scale) * 0.5;

    ctx.save();
    ctx.setTransform(scale, 0, 0, scale, offsetX, offsetY);

    const scrollDist = elapsed * GROUND_SPEED;

    drawSky(elapsed);
    drawMountains(scrollDist);
    drawGroundAndMeadow(scrollDist, elapsed);
    drawAlpaca(elapsed, dt);
    drawParticlesAndForeground(scrollDist, elapsed, dt);

    ctx.restore();
    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
})();
